from pathlib import Path
import os,json,subprocess,numpy as np,pandas as pd,scipy.sparse as sp,itertools
from scipy.stats import false_discovery_control
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
P=Path(__file__).parent;O=P/'HCC_Hallmark_paired_v1';O.mkdir(exist_ok=False);I=P/'HCC_compartment_paired_v2';meta=pd.read_csv(I/'compartment_sample_metadata.tsv',sep='\t',dtype={'donor':str});genes=pd.read_csv(P/'HCC_marker_pair_review_v2/pseudobulk_genes.tsv',sep='\t',index_col=0);X=sp.load_npz(I/'compartment_sample_raw_pseudobulk.npz');wanted=['Hepatocyte_like','Endothelial_enriched_mixed','Stromal_enriched_mixed','Myeloid_enriched_mixed'];keep=meta.compartment.isin(wanted);meta=meta[keep].copy().reset_index(drop=True);X=X[keep.to_numpy()].astype(np.float64);sym=genes.gene_symbol_original.fillna('').astype(str);valid=~sym.isin(['','nan','NA','None']);uni=pd.Index(sym[valid].unique());ix=uni.get_indexer(sym[valid]);X=X[:,valid.to_numpy()]@sp.csr_matrix((np.ones(len(ix)),(np.arange(len(ix)),ix)),shape=(len(ix),len(uni)));dense=X.toarray();expr=np.log2(dense/dense.sum(axis=1)[:,None]*1e6+1);meta['sample_key']=meta.compartment+'__'+meta.donor+'__'+meta.tissue;assert meta.sample_key.is_unique;pd.DataFrame(expr.T,index=uni,columns=meta.sample_key).to_csv(O/'log2CPM_input.tsv',sep='\t');meta.to_csv(O/'sample_metadata.tsv',sep='\t',index=False)
r=f""".libPaths(c('{P/'irGSEA_dependencies_v1/R_project_library_v1'}','{P/'trajectory_dependencies_v1/R_project_library_v1'}',.Library));library(GSVA);library(BiocParallel);d<-'{O}';x<-as.matrix(read.delim(file.path(d,'log2CPM_input.tsv'),row.names=1,check.names=FALSE));gmt<-strsplit(readLines('{P/'F4_official_sources_v1/Hallmark_2025.1_Hs.gmt'}'),'\t');sets<-lapply(gmt,function(z)unique(z[-c(1,2)]));names(sets)<-sapply(gmt,function(z)z[1]);set.seed(0);par<-ssgseaParam(x,sets,minSize=1,maxSize=Inf,normalize=TRUE);sc<-gsva(par,verbose=TRUE,BPPARAM=SerialParam());write.table(sc,file.path(d,'official_ssGSEA_scores.tsv'),sep='\t',quote=FALSE,col.names=NA);writeLines(capture.output(sessionInfo()),file.path(d,'sessionInfo.txt'))
""";(O/'run.R').write_text(r);native=P/'dependency_irgsea_repair_v3/native_dependencies';env=os.environ.copy();env['LD_PRELOAD']=str(native/'lib/libstdc++.so.6')+':'+str(native/'lib/libdeflate.so.0');env['LD_LIBRARY_PATH']=str(native/'lib');
with open(O/'R.log','w') as log:ret=subprocess.run(['/usr/bin/Rscript','--vanilla',str(O/'run.R')],stdout=log,stderr=subprocess.STDOUT,env=env)
assert ret.returncode==0;sc=pd.read_csv(O/'official_ssGSEA_scores.tsv',sep='\t',index_col=0);assert sc.shape[0]==50 and sc.columns.tolist()==meta.sample_key.tolist() and np.isfinite(sc).all().all();results=[]
for name in wanted:
 m=meta[meta.compartment.eq(name)];pairs=[]
 for donor,z in m.groupby('donor'):
  if set(z.tissue)=={'Tumor','AdjNonTumor'}:pairs.append((donor,z.loc[z.tissue.eq('Tumor'),'sample_key'].iloc[0],z.loc[z.tissue.eq('AdjNonTumor'),'sample_key'].iloc[0]))
 n=len(pairs);assert n==(2 if name=='Myeloid_enriched_mixed' else 3);delta=np.array([(sc[t]-sc[a]).to_numpy() for _,t,a in pairs],dtype=np.float64);effect=delta.mean(axis=0);signs=np.array(list(itertools.product([-1,1],repeat=n)));dist=(signs[:,:,None]*delta[None,:,:]).mean(axis=1);pv=(np.abs(dist)>=np.abs(effect)[None,:]-1e-12*(1+np.abs(effect)[None,:])).mean(axis=0);assert pv.min()>=2/2**n;q=false_discovery_control(pv,method='bh');tab=pd.DataFrame({'pathway':sc.index,'mean_paired_score_difference':effect,'pairs':n,'exact_two_sided_p':pv,'BH_q':q})
 for j,(donor,_,_) in enumerate(pairs):tab['paired_score_difference_donor_'+donor]=delta[j]
 tab.to_csv(O/(name+'_paired_Hallmark.tsv'),sep='\t',index=False);fig,ax=plt.subplots(figsize=(7,12));v=max(abs(delta).max(),.001);im=ax.imshow(delta.T,aspect='auto',cmap='RdBu_r',vmin=-v,vmax=v);ax.set_yticks(range(50),sc.index.str.replace('HALLMARK_',''),fontsize=7);ax.set_xticks(range(n),[d for d,_,_ in pairs]);ax.set_title(name+' | '+str(n)+' actual patient pairs\nPseudobulk ssGSEA; exploratory, no significant pathways');ax.set_xlabel('Patient: tumor minus paired adjacent');fig.colorbar(im,ax=ax,label='Paired ssGSEA score difference');fig.tight_layout();fig.savefig(O/(name+'_paired_Hallmark.png'),dpi=160);plt.close(fig);results.append({'compartment':name,'pairs':n,'min_p':float(pv.min()),'q_below05':int((q<.05).sum())})
v={'method':'Official GSVA ssGSEA, normalized scores on log2(CPM+1) donor/tissue pseudobulk. Duplicate gene symbols summed; blank/NA symbols excluded only for gene-set matching. Not original cell-level averaging or unavailable custom sets.','results':results,'gene_symbols_used':len(uni),'source_features_without_symbol':int((~valid).sum()),'MT_QC':'Unavailable; corrected NA input retained','clinical':'Patient1 NAFLD; patients2/3 NASH; adjacent is not healthy','label_limit':'Mixed enriched compartments are provisional, not pure lineages or malignant identities'};(O/'validation.json').write_text(json.dumps(v,indent=2));print(json.dumps(v))
